const connections = {
  active: 0,
  open() {
    this.active += 1;
    let closed = false;
    return () => {
      if (!closed) { this.active -= 1; closed = true; }
    };
  }
};
function Listener() {
  React.useEffect(() => {
    const close = connections.open();
    return close;
  }, []);
  return <p>Listener mounted</p>;
}
function App() {
  const [shown, setShown] = React.useState(true);
  return <main>
    <button onClick={() => setShown(s => !s)}>Toggle listener</button>
    <React.StrictMode>{shown && <Listener />}</React.StrictMode>
  </main>;
}
```

```react
const connections = {
  active: 0,
  open() {
    this.active += 1;
    let closed = false;
    return () => {
      if (!closed) { this.active -= 1; closed = true; }
    };
  }
};
function Listener() {
  React.useEffect(() => {
    const close = connections.open();
    return undefined;
  }, []);
  return <p>Listener mounted</p>;
}
function App() {
  const [shown, setShown] = React.useState(true);
  return <main>
    <button onClick={() => setShown(s => !s)}>Toggle listener</button>
    <React.StrictMode>{shown && <Listener />}</React.StrictMode>
  </main>;
}
```
Returning undefined instead of close means no cleanup is registered. Removing Listener then leaves active resources behind. In a development build, the extra setup/cleanup rehearsal can expose the leak even earlier. The correct version has one live resource while mounted and zero after removal.

